const sigDigits = (s) => s.replace(/^-/, '').split(/e/i)[0].replace('.', '').replace(/^0+/, '').replace(/0+$/, '');

export default async (check) => {
  for (const id of ['half', 'single', 'double']) {
    const f = F.FORMATS[id];
    let bits = 0, exact = 0, err = 0, nb = 0, ul = 0, sh = 0, n = 0, bad = '';
    for (const c of CASES) {
      const r = c[id], b = F.encode(c.s, f);
      n++;
      if ('0x' + b.toString(16) === r.bits) bits++; else if (!bad) bad = `${c.s}: ${'0x' + b.toString(16)} want ${r.bits}`;
      if (!('exact' in r)) { exact++; err++; nb++; ul++; sh++; continue; }
      const d = F.decode(b, f), p = F.parseDecimal(c.s);
      if (F.ratToDecimal(d.r) === r.exact) exact++;
      if (F.ratToDecimal(F.sub(d.r, p.r)) === r.err) err++;
      if ('0x' + F.step(b, f, true).toString(16) === r.up && '0x' + F.step(b, f, false).toString(16) === r.down) nb++;
      const u = F.ulp(b, f); if (r.ulp == null || F.ratToDecimal(u) === r.ulp) ul++;
      const s = F.shortest(b, f); if (F.encode(s, f) === b && (Number(s) === Number(r.short) || Object.is(Number(s), -0)) && sigDigits(s) === sigDigits(r.short)) sh++; else if (!bad) bad = `short ${c.s}: ${s} vs ${r.short}`;
    }
    check(`float: ${id} bit patterns match numpy/struct (${bits}/${n}) ${bad}`, bits === n);
    check(`float: ${id} exact stored values match Fraction (${exact}/${n})`, exact === n);
    check(`float: ${id} exact rounding errors match Fraction (${err}/${n})`, err === n);
    check(`float: ${id} next up and down match np.nextafter (${nb}/${n})`, nb === n);
    check(`float: ${id} ULP matches np.spacing (${ul}/${n})`, ul === n);
    check(`float: ${id} shortest round-trip decimal has numpy's digits (${sh}/${n})`, sh === n);
  }
  { const twice = CASES.filter((c) => ['half', 'single'].some((id) => c[id].np_direct && c[id].np_direct !== c[id].bits)); check(`float: correct rounding where a detour through double rounds twice (${twice.length} cases)`, twice.length >= 1 && F.encode('1.00000005960464477539062501', F.FORMATS.single) === 0x3f800001n); }
  const D = F.FORMATS.double, S1 = F.FORMATS.single, H = F.FORMATS.half;
  check('float: 0.1 as a double is 0x3FB999999999999A, exactly 0.1000000000000000055511151231257827021181583404541015625', F.hex(F.encode('0.1', D), D) === '0x3FB999999999999A' && F.ratToDecimal(F.decode(F.encode('0.1', D), D).r) === '0.1000000000000000055511151231257827021181583404541015625');
  check('float: decode parts of -2.5 single (sign 1, exponent 128, e = 1)', (() => { const d = F.decode(F.encode('-2.5', S1), S1); return d.sign === 1 && d.expField === 128 && d.e === 1 && d.kind === 'normal'; })());
  check('float: kinds', F.decode(0n, H).kind === 'zero' && F.decode(1n, H).kind === 'subnormal' && F.decode(0x7c00n, H).kind === 'infinity' && F.decode(0x7e00n, H).kind === 'nan');
  check('float: inf, -inf and NaN encode', F.encode('inf', H) === 0x7c00n && F.encode('-Infinity', S1) === 0xff800000n && F.encode('NaN', D) === 0x7ff8000000000000n);
  check('float: specials (half: largest 65504, smallest subnormal 2^-24)', (() => { const s = Object.fromEntries(F.specials(H).map((x) => [x.name, x.bits])); return F.toNumber(s['Largest finite'], H) === 65504 && F.toNumber(s['Smallest subnormal'], H) === 2 ** -24 && F.toNumber(s['Smallest normal'], H) === 2 ** -14 && F.toNumber(s['One plus machine epsilon'], H) === 1 + 2 ** -10; })());
  check('float: double specials match JS constants', (() => { const s = Object.fromEntries(F.specials(D).map((x) => [x.name, x.bits])); return F.toNumber(s['Largest finite'], D) === Number.MAX_VALUE && F.toNumber(s['Smallest subnormal'], D) === Number.MIN_VALUE && F.toNumber(s['One plus machine epsilon'], D) - 1 === Number.EPSILON; })());
  check('float: stepping across zero and to infinity', F.step(0n, H, false) === 0x8001n && F.step(0x8001n, H, true) === 0x8000n && F.step(0x7bffn, H, true) === 0x7c00n && F.step(0x7c00n, H, true) === 0x7c00n && F.step(0x7c00n, H, false) === 0x7bffn);
  check('float: parseBits hex and binary', F.parseBits('0x3C00', H) === 0x3c00n && F.parseBits('0011110000000000', H) === 0x3c00n && (() => { try { F.parseBits('0x1FFFF', H); return false; } catch (e) { return e.message.includes('more than 16'); } })());
  check('float: parseDecimal refuses words', (() => { try { F.parseDecimal('abc'); return false; } catch (e) { return e.message.includes('"abc" is not a number'); } })());
  check('float: ratToNumber', F.ratToNumber({ neg: true, num: 1n, den: 3n }) === -1 / 3 && F.ratToNumber(F.parseDecimal('6.02214076e23').r) === 6.02214076e23);
};
